import random
import string

def generate():
    characters = string.ascii_letters + string.digits
    return ''.join(random.choice(characters) for _ in range(8))

from generate import generate
from open_pdf import open_pdf


def iterate(pdf_path: str):
    while True:
        password = generate()
        try:
            open_pdf(pdf_path, password)
            print(f'Successfully opened PDF with password: {password}')
            break  # Exit loop on success
        except Exception as e:
            print(f'Failed to open PDF with password: {password}. Error: {e}')
